import { TEAM_LABEL, TEMPLATES, type Team } from "./agent-gallery/data";
import { TemplateCard } from "./agent-gallery/template-card";
import { APP_NAME } from "./parts/app-mark";

type Filter = "all" | Team;

// Critically damped: 2 * sqrt(400) is 40, so cards glide to their new cells without a wobble.
const GLIDE: Transition = { type: "spring", stiffness: 400, damping: 40, mass: 1 };
const INSTANT: Transition = { duration: 0 };

const FILTERS: Filter[] = ["all", "front-desk", "practitioners", "billing", "managers"];

/** Whether a template matches the search words, by its name, line, model or app names. */
function matches(template: (typeof TEMPLATES)[number], query: string) {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (words.length === 0) return true;
  const haystack = [template.name, template.line, template.model, ...template.apps.map((app) => APP_NAME[app])].join(" ").toLowerCase();
  return words.every((word) => haystack.includes(word));
}

/**
 * A gallery of ready-made agents for Fernhill clinics. Search and team chips
 * narrow the grid: removed cards fade out and the rest glide to their new
 * cells. Each card previews a sample run and installs in place.
 */
export function AgentGallery({ className }: { className?: string }) {
  const [query, setQuery] = useState("");
  const [team, setTeam] = useState<Filter>("all");
  const reduceMotion = useReducedMotion();
  const titleId = useId();
  const searchId = useId();

  const searched = TEMPLATES.filter((template) => matches(template, query));
  const shown = searched.filter((template) => team === "all" || template.team === team);
  const count = (filter: Filter) => searched.filter((template) => filter === "all" || template.team === filter).length;

  const options = FILTERS.map((value) => ({
    value,
    label: (
      <span className="flex items-center gap-1.5 whitespace-nowrap">
        {value === "all" ? "All" : TEAM_LABEL[value]}
        <span className="text-xs text-muted-foreground tabular-nums">{count(value)}</span>
      </span>
    ),
  }));

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-col gap-4 border-b border-border px-5 py-4">
        <div className="flex flex-wrap items-end justify-between gap-x-6 gap-y-3">
          <div className="min-w-0">
            <h2 id={titleId} className="text-base font-semibold">
              Agent templates
            </h2>
            <p className="text-sm text-muted-foreground">Ready-made agents that work in the tools your clinic already uses.</p>
          </div>
          <div className="relative w-full @lg:w-64">
            <label htmlFor={searchId} className="sr-only">
              Search agents or apps
            </label>
            <Input
              id={searchId}
              type="search"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder="Search agents or apps"
            />
          </div>
        </div>
        <div className="-mx-5 overflow-x-auto scroll-fade-effect-x scrollbar-none px-5 pb-1">
          <SegmentedControl aria-label="Team" options={options} value={team} onValueChange={setTeam} />
        </div>
      </header>

      <div className="p-5">
        <p aria-live="polite" className="sr-only">
          {shown.length === 1 ? "1 agent" : `${shown.length} agents`}
        </p>
        {shown.length === 0 ? (
          <div className="flex flex-col items-center gap-3 py-10 text-center">
            <p className="text-sm text-muted-foreground">No agent matches {query ? `"${query}"` : "this team"}.</p>
            <Button
              variant="outline"
              size="sm"
              onClick={() => {
                setQuery("");
                setTeam("all");
              }}
            >
              Clear search and team
            </Button>
          </div>
        ) : (
          <motion.ul layout={!reduceMotion} transition={reduceMotion ? INSTANT : GLIDE} className="grid gap-3 @lg:grid-cols-2 @4xl:grid-cols-3">
            <AnimatePresence mode="popLayout" initial={false}>
              {shown.map((template) => (
                <motion.li
                  key={template.id}
                  layout={!reduceMotion}
                  initial={reduceMotion ? false : { opacity: 0, scale: 0.97 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={reduceMotion ? { opacity: 0, transition: INSTANT } : { opacity: 0, scale: 0.97, transition: { duration: 0.15 } }}
                  transition={reduceMotion ? INSTANT : GLIDE}
                >
                  <TemplateCard template={template} />
                </motion.li>
              ))}
            </AnimatePresence>
          </motion.ul>
        )}
      </div>
    </BlockFrame>
  );
}

