type Mode = "browse" | "preview" | "workspace" | "access" | "installed";

const BACK = { browse: "browse", preview: "browse", workspace: "browse", access: "workspace", installed: "installed" } satisfies Record<Mode, Mode>;

/** Props for one template card. */
export interface TemplateCardProps {
  template: Template;
}

/**
 * One agent template. Preview plays a sample run inside the card. Install
 * walks through a workspace and app access inside the card, then confirms
 * with a check. Escape steps back one stage, and focus moves to each new stage.
 */
export function TemplateCard({ template }: TemplateCardProps) {
  const [mode, setMode] = useState<Mode>("browse");
  const [workspace, setWorkspace] = useState(WORKSPACES[0]!);
  const reduceMotion = useReducedMotion();
  const body = useRef<HTMLDivElement>(null);
  const moved = useRef(false);
  const titleId = useId();

  useEffect(() => {
    if (!moved.current) return;
    moved.current = false;
    body.current?.querySelector<HTMLElement>("input:checked, button:not(:disabled), [tabindex='0']")?.focus();
  }, [mode]);

  const go = (next: Mode) => {
    moved.current = true;
    setMode(next);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    if (event.key !== "Escape" || BACK[mode] === mode) return;
    event.preventDefault();
    go(BACK[mode]);
  };

  const installs = template.installs + (mode === "installed" ? 1 : 0);

  return (
    <article aria-labelledby={titleId} onKeyDown={onKeyDown} className="flex h-full flex-col gap-3 rounded-xl border border-border p-4">
      <div className="flex items-center justify-between gap-3">
        <span className="flex -space-x-1" role="img" aria-label={`Uses ${template.apps.map((app) => APP_NAME[app]).join(", ")}`}>
          {template.apps.map((app) => (
            <AppMark key={app} app={app} className="ring-2 ring-card" />
          ))}
        </span>
        <span className="truncate text-xs text-muted-foreground">{template.model}</span>
      </div>
      <div className="flex flex-col gap-1">
        <h3 id={titleId} className="text-sm font-semibold">
          {template.name}
        </h3>
        <p className="text-sm text-muted-foreground">{template.line}</p>
      </div>

      <motion.div
        key={mode}
        ref={body}
        initial={reduceMotion ? false : { opacity: 0, y: 4 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.18 }}
        className="mt-auto flex flex-col gap-3"
      >
        {mode === "browse" ? (
          <div className="flex flex-wrap items-center justify-between gap-2">
            <Stats rating={template.rating} installs={installs} />
            <div className="flex gap-1.5">
              <Button variant="ghost" size="sm" aria-label={`Preview ${template.name}`} onClick={() => go("preview")}>
                Preview
              </Button>
              <Button variant="outline" size="sm" aria-label={`Install ${template.name}`} onClick={() => go("workspace")}>
                Install
              </Button>
            </div>
          </div>
        ) : null}
        {mode === "preview" ? <SampleRun template={template} onBack={() => go("browse")} onInstall={() => go("workspace")} /> : null}
        {mode === "workspace" || mode === "access" ? (
          <InstallFlow
            template={template}
            step={mode}
            workspace={workspace}
            onWorkspace={setWorkspace}
            onNext={() => go("access")}
            onBack={() => go(BACK[mode])}
            onInstall={() => go("installed")}
          />
        ) : null}
        {mode === "installed" ? (
          <div className="flex flex-wrap items-center justify-between gap-2">
            <p role="status" tabIndex={0} className="flex items-center gap-1.5 rounded-sm text-sm font-medium text-marketing-green-ink outline-none focus-visible:ring-2 focus-visible:ring-ring">
              <motion.span initial={reduceMotion ? false : { scale: 0.4, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={{ type: "spring", stiffness: 500, damping: 45 }}>
                <CircleCheckIcon aria-hidden="true" className="size-4" />
              </motion.span>
              Installed in {workspace.name}
            </p>
            <Stats rating={template.rating} installs={installs} />
          </div>
        ) : null}
      </motion.div>
    </article>
  );
}

/** The rating and install count, each with its own icon and spoken name. */
function Stats({ rating, installs }: { rating: number; installs: number }) {
  return (
    <span className="flex items-center gap-3 text-xs text-muted-foreground tabular-nums">
      <span className="flex items-center gap-1">
        <StarIcon aria-hidden="true" className="size-3.5 text-chart-5" />
        <span className="sr-only">Rated </span>
        {rating.toFixed(1)}
      </span>
      <span className="flex items-center gap-1">
        <DownloadIcon aria-hidden="true" className="size-3.5" />
        {formatTokens(installs)}
        <span className="sr-only"> installs</span>
      </span>
    </span>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const CENTS = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 });

/** Seconds as a short clock reading, such as "48s" or "2m 05s". */
export function formatSeconds(seconds: number) {
  const whole = Math.max(0, Math.round(seconds));
  if (whole < 60) return `${whole}s`;
  const minutes = Math.floor(whole / 60);
  const rest = whole % 60;
  if (minutes < 60) return `${minutes}m ${String(rest).padStart(2, "0")}s`;
  return `${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, "0")}m`;
}

/** A token count, such as "840" or "12.4K". */
export const formatTokens = (value: number) => (value < 1000 ? WHOLE.format(Math.round(value)) : COMPACT.format(value));

/** A cost with cents, such as "$0.42". */
export const formatCost = (value: number) => CENTS.format(value);

/** A whole number with separators. */
export const formatCount = (value: number) => WHOLE.format(Math.round(value));

/** Roll formats for `NumberTicker`. Module constants, because the ticker memoises its formatter on them. */
export const ROLL_WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };
/** One decimal place, for a score or a percent. */
export const ROLL_ONE_PLACE: Intl.NumberFormatOptions = { minimumFractionDigits: 1, maximumFractionDigits: 1 };
/** Dollars with cents. */
export const ROLL_CENTS: Intl.NumberFormatOptions = { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 };

"use client";

import { useId, useState } from "react";

import { CheckIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
