import { APP_NAME, AppMark } from "../parts/app-mark";
import { type Template, WORKSPACES, type Workspace } from "./data";

/** Props for the install steps inside a card. */
export interface InstallFlowProps {
  template: Template;
  step: "workspace" | "access";
  workspace: Workspace;
  onWorkspace: (workspace: Workspace) => void;
  onNext: () => void;
  onBack: () => void;
  onInstall: () => void;
}

/**
 * The two install steps. First a person picks a workspace from a radio group,
 * where arrow keys move. Then they allow each app the agent needs, one by one,
 * and Install unlocks once every app is allowed.
 */
export function InstallFlow({ template, step, workspace, onWorkspace, onNext, onBack, onInstall }: InstallFlowProps) {
  const [allowed, setAllowed] = useState<Set<string>>(() => new Set());
  const legendId = useId();

  if (step === "workspace") {
    return (
      <div className="flex flex-col gap-2">
        <p id={legendId} className="mb-2 text-sm font-medium">
          Install {template.name} in
        </p>
        <RadioGroup
          aria-labelledby={legendId}
          value={workspace.id}
          onValueChange={(id) => {
            const next = WORKSPACES.find((item) => item.id === id);
            if (next) onWorkspace(next);
          }}
          className="contents"
        >
          {WORKSPACES.map((item) => {
            const checked = item.id === workspace.id;
            return (
              <label
                key={item.id}
                className={cn(
                  "relative isolate flex cursor-pointer items-center gap-3 rounded-lg border px-3 py-2 has-focus-visible:ring-2 has-focus-visible:ring-ring",
                  checked ? "border-foreground" : "border-border",
                )}
              >
                <span aria-hidden="true" className={cn("absolute inset-0 -z-10 rounded-lg", checked ? "bg-muted/60" : null)} />
                <RadioGroupItem value={item.id} />
                <span className="flex min-w-0 flex-col">
                  <span className="truncate text-sm">{item.name}</span>
                  <span className="truncate text-xs text-muted-foreground">{item.line}</span>
                </span>
              </label>
            );
          })}
        </RadioGroup>
        <div className="mt-1 flex justify-end gap-2">
          <Button variant="ghost" size="sm" onClick={onBack}>
            Cancel
          </Button>
          <Button size="sm" onClick={onNext}>
            Next
          </Button>
        </div>
      </div>
    );
  }

  const ready = template.apps.every((app) => allowed.has(app));
  return (
    <div className="flex flex-col gap-2">
      <h4 className="text-sm font-medium">Allow access in {workspace.name}</h4>
      <ul className="flex flex-col gap-1.5">
        {template.apps.map((app) => {
          const ok = allowed.has(app);
          return (
            <li key={app} className="flex items-center gap-3 rounded-lg border border-border px-3 py-1.5">
              <AppMark app={app} />
              <span className="min-w-0 flex-1 truncate text-sm">{APP_NAME[app]}</span>
              {ok ? (
                <span className="flex h-8 items-center gap-1 text-xs font-medium text-marketing-green-ink">
                  <CheckIcon aria-hidden="true" className="size-3.5" />
                  Allowed
                </span>
              ) : (
                <Button variant="outline" size="sm" aria-label={`Allow ${APP_NAME[app]}`} onClick={() => setAllowed((set) => new Set(set).add(app))}>
                  Allow
                </Button>
              )}
            </li>
          );
        })}
      </ul>
      <p aria-live="polite" className="text-xs text-muted-foreground">
        {allowed.size} of {template.apps.length} apps allowed
      </p>
      <div className="flex justify-end gap-2">
        <Button variant="ghost" size="sm" onClick={onBack}>
          Back
        </Button>
        <Button size="sm" onClick={onInstall} disabled={!ready}>
          Install
        </Button>
      </div>
    </div>
  );
}

