/**
 * A short replay of what the agent did on a sample day. Steps arrive one by
 * one; the step in progress shimmers, and finished steps get a check.
 */
export function SampleRun({ template, onBack, onInstall }: SampleRunProps) {
  const reduceMotion = useReducedMotion();
  const total = template.sample.length;
  const [done, setDone] = useState(reduceMotion ? total : 0);
  useInterval(() => setDone((count) => count + 1), done < total ? 900 : null);

  return (
    <div className="flex flex-col gap-3">
      <h4 className="flex items-center gap-2 text-sm font-medium">
        <SparklesIcon aria-hidden="true" className="size-4 text-chart-4" />
