import { useEffect, useRef, useState } from "react";

/**
 * Calls `callback` every `delay` milliseconds while `delay` is a number, and
 * stops when it is null or the component unmounts. The latest callback always runs.
 */
export function useInterval(callback: () => void, delay: number | null) {
  const saved = useRef(callback);
  useEffect(() => {
    saved.current = callback;
  }, [callback]);
  useEffect(() => {
    if (delay === null) return;
    const id = window.setInterval(() => saved.current(), delay);
    return () => window.clearInterval(id);
  }, [delay]);
}

/**
 * Whole seconds since `running` last turned true. The count holds while
 * `running` is false and starts again from zero on `resetKey` change.
 */
export function useElapsed(running: boolean, resetKey: string | number = 0) {
  const [state, setState] = useState({ key: resetKey, seconds: 0 });
  // A new reset key starts the count again, adjusted during render rather than in an effect.
  if (state.key !== resetKey) setState({ key: resetKey, seconds: 0 });
  useInterval(() => setState((current) => ({ ...current, seconds: current.seconds + 1 })), running ? 1000 : null);
  return state.key === resetKey ? state.seconds : 0;
}

/**
 * Runs a list of timed steps one after another. Each step waits its `after`
 * milliseconds, then calls `run`. Every pending timer clears on unmount or when `key` changes.
 */
export function useSchedule(steps: { after: number; run: () => void }[] | null, key: string | number) {
  const saved = useRef(steps);
  useEffect(() => {
    saved.current = steps;
  });
  useEffect(() => {
    const list = saved.current;
    if (!list) return;
    const ids: number[] = [];
    let total = 0;
    for (const step of list) {
      total += step.after;
      ids.push(window.setTimeout(step.run, total));
    }
    return () => ids.forEach((id) => window.clearTimeout(id));
  }, [key]);
}

"use client";

import { motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for a line of text that shimmers while its work runs. */
export interface ShimmerTextProps {
  text: string;
  /** The text shimmers only while this is true. */
  active: boolean;
  className?: string;
}

/**
 * A short line, such as the verb of a running step, with a light band that
 * sweeps across it while `active` is true. With reduced motion the text stays still.
 */
export function ShimmerText({ text, active, className }: ShimmerTextProps) {
  const reduceMotion = useReducedMotion();
  if (!active || reduceMotion) return <span className={className}>{text}</span>;
  return (
    <motion.span
      className={cn(
        "bg-linear-to-r from-muted-foreground via-foreground to-muted-foreground bg-size-(--shimmer) bg-clip-text text-transparent",
        className,
      )}
      style={
        // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
        { "--shimmer": "200% 100%" } as VarStyle
      }
      initial={{ backgroundPosition: "100% 0" }}
      animate={{ backgroundPosition: "-100% 0" }}
      transition={{ duration: 1.6, ease: "linear", repeat: Infinity }}
    >
      {text}
    </motion.span>
  );
}

import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };
